  notif_interview_proposed: { tr:'Mülakat için saatler önerildi.', en:'Interview times were proposed.', ru:'Предложены даты собеседования.', kk:'Сұхбат уақыттары ұсынылды.', de:'Interviewzeiten vorgeschlagen.', th:'มีการเสนอเวลาสัมภาษณ์', uz:'Suhbat vaqtlari taklif qilindi.', fa:'زمان‌های مصاحبه پیشنهاد شد.', ky:'Маек убакыттары сунушталды.', tk:'Söhbet wagtlary teklip edildi.' },
  notif_interview_scheduled: { tr:'Aday mülakat saatini seçti.', en:'Candidate picked an interview time.', ru:'Кандидат выбрал время собеседования.', kk:'Үміткер сұхбат уақытын таңдады.', ky:'Талапкер маектин убактысын тандады.', uz:'Nomzod suhbat vaqtini tanladi.', tk:'Dalaşgär söhbetdeşlik wagtyny saýlady.', de:'Kandidat hat eine Interviewzeit gewählt.', th:'ผู้สมัครเลือกเวลาสัมภาษณ์แล้ว', fa:'داوطلب زمان مصاحبه را انتخاب کرد.' },
  notif_interview_scheduled_detail: { tr:'{code} mülakat saatini seçti: {slot}', en:'{code} selected an interview time: {slot}', ru:'{code} выбрал(а) время: {slot}', kk:'{code} сұхбат уақытын таңдады: {slot}', ky:'{code} маек убактысын тандады: {slot}', uz:'{code} suhbat vaqtini tanladi: {slot}', tk:'{code} söhbet wagtyny saýlady: {slot}', de:'{code} hat eine Zeit gewählt: {slot}', th:'{code} เลือกเวลา: {slot}', fa:'{code} زمان را انتخاب کرد: {slot}' },
