  passport_cam_hint: { tr:'Pasaportun fotoğraflı sayfasını çerçeveye yerleştirin', en:'Place the passport photo page inside the frame', ru:'Поместите страницу с фото паспорта в рамку', kk:'Төлқұжаттың фотосуреті бар бетін жақтауға қойыңыз', de:'Passfotoseite in den Rahmen legen', th:'วางหน้ารูปถ่ายหนังสือเดินทางในกรอบ', uz:'Pasportning rasmli sahifasini ramkaga joylang', fa:'صفحه عکس‌دار پاسپورت را داخل کادر قرار دهید', ky:'Паспорттун сүрөттүү бетин рамкага коюңуз', tk:'Pasportyň suratly sahypasyny çarçuwa goýuň' },
  passport_cam_perm: { tr:'Pasaport çekmek için kamera izni gerekli.', en:'Camera permission is required to capture the passport.', ru:'Для съёмки паспорта нужен доступ к камере.', kk:'Төлқұжатты түсіру үшін камера рұқсаты қажет.', de:'Kamerazugriff erforderlich.', th:'ต้องอนุญาตให้ใช้กล้องเพื่อถ่ายหนังสือเดินทาง', uz:'Pasportni suratga olish uchun kamera ruxsati kerak.', fa:'برای عکس‌برداری از پاسپورت دسترسی دوربین لازم است.', ky:'Паспортту тартуу үчүн камера уруксаты керек.', tk:'Pasporty surata almak üçin kamera rugsady gerek.' },
